import os
import json
from typing import Any, Dict, List, Optional

from openai import OpenAI


def extract_invoice_fields(invoice_text: str) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using OpenAI's hosted API.
    """
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    schema = {
        "name": "invoice_extraction",
        "schema": {
            "type": "object",
            "properties": {
                "vendor": {"type": ["string", "null"]},
                "date": {"type": ["string", "null"], "description": "Invoice date in ISO 8601 if possible"},
                "total": {"type": ["string", "null"], "description": "Invoice total amount as a string"},
                "line_items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "description": {"type": ["string", "null"]},
                            "quantity": {"type": ["number", "string", "null"]},
                            "unit_price": {"type": ["string", "number", "null"]},
                            "amount": {"type": ["string", "number", "null"]},
                        },
                        "required": ["description", "quantity", "unit_price", "amount"],
                        "additionalProperties": False,
                    },
                },
            },
            "required": ["vendor", "date", "total", "line_items"],
            "additionalProperties": False,
        },
        "strict": True,
    }

    prompt = (
        "Extract the vendor, invoice date, total amount, and line items from the invoice text. "
        "Return only structured data matching the schema.\n\n"
        f"INVOICE TEXT:\n{invoice_text}"
    )

    response = client.responses.create(
        model="gpt-4.1-mini",
        input=prompt,
        response_format={"type": "json_schema", "json_schema": schema},
    )

    output_text = getattr(response, "output_text", None)
    if not output_text:
        try:
            output_text = response.output[0].content[0].text
        except Exception as exc:
            raise ValueError("Unable to parse response from the extraction service") from exc

    data = json.loads(output_text)

    # Normalize expected top-level fields
    return {
        "vendor": data.get("vendor"),
        "date": data.get("date"),
        "total": data.get("total"),
        "line_items": data.get("line_items", []),
    }
